"""批1新增关卡生产器。冻结输入只读；逐题题面、路线、错因均在配置中。"""
from pathlib import Path
import json, math, copy
P=Path(__file__).resolve().parents[2]
SRC=json.loads((P/'v4/data-inequality.json').read_text())
CARDS={c['n']:c for c in SRC['cards']}
OUT=P/'关卡/第一章/战斗'
D=[]
def add(n,k,idx,**kw):
 c=CARDS[n];s=c if idx==-1 else c['variants'][idx]
 kw.update(n=n,k=k,source='q' if idx==-1 else f'variants[{idx}]',q=s['q'],source_steps=s['steps'])
 D.append(kw)
def garden(expr,a,opt,val,kind='最小值',op='>',b=None,change=None):
 dom={'op':op,'a':a}
 if b is not None:dom['b']=b
 cs=change or [{'op':'>','a':a+(opt-a)/2},{'op':'≥','a':opt+(b-opt)/2 if b else opt+1},{'op':'>','a':opt+(b-opt)/2 if b else opt+1}]
 return {'类':kind,'式':expr,'定义域':dom,'原取等':opt,'原最小' if kind=='最小值' else '原最大':val,'改':cs,'自出':{'op':['>','≥'],'a':sorted(set([z['a'] for z in cs]))}}
# routes: 学法、理由、该路线题板。所有路线随后共用检查取等与代回步骤。
add(6,1,-1,terms=[r'$x$',r'$2y$'],discover=r'担子的两端是 $x$ 和 $2y$，和为 $2$。',domain=r'$x>0,y>0$，所以 $x>0,2y>0$。',routes=[('放缩','和已经固定',r'玛尔嘉：$x+2y=2\ge2\sqrt{2xy}$，所以 $xy\le\frac12$。'),('方程思想','先解出一个字母',r'芭兰：$y=1-\frac x2$，$xy=\frac12-\frac12(x-1)^2\le\frac12$。')],eq=r'$x=2y$，联立原条件得 $x=1,y=\frac12$。',wrong=r'$x=y=1$',pit=r'这时 $x+2y=3$，不等于题里的 $2$。',calc=r'$2\ge2\sqrt{2xy}\Rightarrow xy\le\square$',fill=[('最大值',.5),('取到时 $x=$',1)],answer={'最大值':.5,'取到':r'x=1,y=1/2'},check=r'$1+2\times\frac12=2$，$1\times\frac12=\frac12$。',g=garden('x*(2-x)/2',0,1,.5,'最大值',b=2),codes=['I-chain-15','I07','I03'])
add(6,2,0,terms=[r'$x$',r'$2y$'],discover=r'$x\cdot2y=2xy=1$，是定值。',domain=r'$x>0,y>0$，两项 $x,2y$ 都正。',routes=[('放缩','两项乘起来不变',r'玛尔嘉：$x+2y\ge2\sqrt{2xy}=2$。'),('方程思想','消去一个字母',r'芭兰：$y=1/(2x)$，$x+2y-2=(x-1)^2/x\ge0$。')],eq=r'$x=2y$，所以 $x=1,y=\frac12$。',wrong=r'$x=y=\frac12$',pit=r'两数的积是 $1/4$，不满足 $xy=1/2$。',calc=r'$x+2y\ge2\sqrt1=\square$',fill=[('最小值',2),('取到时 $x=$',1)],answer={'最小值':2,'取到':'x=1,y=1/2'},check=r'$xy=1/2$，$x+2y=1+1=2$。',g=garden('x+1/x',0,1,2),codes=['I07','I03','I04'])
add(6,3,1,terms=[r'$3x$',r'$y$'],discover=r'两端是 $3x$ 和 $y$，和为 $6$。',domain=r'$x>0,y>0$，所以 $3x,y$ 均为正数。',routes=[('方程思想','消去另一端',r'芭兰：$y=6-3x$，$xy=3-3(x-1)^2\le3$。'),('放缩','固定和限制积',r'玛尔嘉：$6\ge2\sqrt{3xy}$，得 $xy\le3$。')],eq=r'$3x=y$，与 $3x+y=6$ 联立得 $x=1,y=3$。',wrong=r'$x=y=\frac32$',pit=r'虽然满足和，但两项 $3x,y$ 不相等，积为 $9/4<3$。',calc=r'$3xy\le9\Rightarrow xy\le\square$',fill=[('最大值',3),('取到时 $x=$',1)],answer={'最大值':3,'取到':'x=1,y=3'},check=r'$3\times1+3=6$，$xy=3$。',g=garden('x*(6-3*x)',0,1,3,'最大值',b=2),codes=['I-chain-15','I07','I03'])
add(7,1,-1,terms=[r'$x$',r'$1/x$'],discover=r'两只手的积是 $1$，但 $x$ 不能小于 $2$。',domain=r'$x\ge2$；公式取等需要的 $x=1$ 不在范围内。',routes=[('函数思想','先看允许的那一段',r'芙洛：$v>u\ge2$ 时，$f(v)-f(u)=(v-u)(1-1/(uv))>0$，所以在左端 $x=2$ 最小。'),('构造','和允许的端点作差',r'法比娅：$x+1/x-5/2=(x-2)(2x-1)/(2x)\ge0$。')],eq=r'$x=2$ 时差为 $0$，最小值为 $5/2$。',wrong=r'$x=1$，最小值为 $2$',pit=r'$x=1$ 不满足 $x\ge2$。下界 $2$ 在这里取不到。',calc=r'$f(2)=2+1/2=\square$',fill=[('最小值',2.5),('取到时 $x=$',2)],answer={'最小值':2.5,'取到':'x=2'},check=r'$x=2$ 合法，$2+1/2=5/2$。',extra=[r'$x\ge2$，故 $x>0$。',r'$x+1/x-5/2=\dfrac{(x-2)(2x-1)}{2x}\ge0$。',r'当且仅当 $x=2$ 时，等号成立，所以最小值为 $5/2$。'],g=garden('x+1/x',2,2,2.5,op='≥',change=[{'op':'≥','a':2},{'op':'≥','a':3},{'op':'>','a':3}]),codes=['I-chain-06','I03','I04'],equal_visual=False)
add(7,2,0,terms=[r'$x$',r'$9/x$'],discover=r'两项积为 $9$，且 $2\le x\le4$。',domain=r'$x=3$ 在区间内；最大值还要比较两端。',routes=[('函数思想','两端和转折都看',r'芙洛：$f(v)-f(u)=(v-u)(1-9/(uv))$。$[2,3]$ 上减、$[3,4]$ 上增；最小在 $3$，最大比较 $2,4$。'),('构造','作差卡住上界',r'法比娅：$f(x)-6=(x-3)^2/x\ge0$；$13/2-f(x)=(x-2)(9-2x)/(2x)\ge0$。')],eq=r'最小值在 $x=3$ 取到，最大值在 $x=2$ 取到。',wrong=r'$x=4$ 时最大，因为它在最右边',pit=r'$f(4)=25/4<13/2=f(2)$。不能只看字母最大。',calc=r'$f(3)=6,\quad f(2)=13/2$',fill=[('最小值',6),('最大值',6.5)],answer={'最小值':6,'最大值':6.5,'取到':'最小x=3，最大x=2'},check=r'$f(3)=6$；$f(2)=13/2>f(4)=25/4$。',g=garden('x+9/x',2,3,6,op='≥',b=4),codes=['I-chain-06','I03','I04'],layers=5)
add(7,3,1,terms=[r'$3x$',r'$1/x$'],discover=r'$2y=1/x$，目标是 $3x+1/x$。',domain=r'$x>0$，两项均正且积为 $3$。',routes=[('整体代换','把两项看成一对',r'塔莉：令 $u=\sqrt3 x>0$，原式 $=\sqrt3(u+1/u)\ge2\sqrt3$。'),('构造','凑出平方差',r'法比娅：$3x+1/x-2\sqrt3=(\sqrt3 x-1)^2/x\ge0$。')],eq=r'$3x=1/x$，所以 $x^2=1/3$，$x=\sqrt3/3,y=\sqrt3/2$。',wrong=r'$x=y=\sqrt2/2$',pit=r'两字母相等不代表 $3x=2y$，因此不能取等。',calc=r'$3x+1/x\ge A\sqrt3,\quad x^2=B$',fill=[('系数 $A=$',2),('$B=$',1/3)],answer={'最小值':r'2\sqrt3','取到':r'x=\sqrt3/3,y=\sqrt3/2'},check=r'$xy=1/2$，$3x=2y=\sqrt3$，总和为 $2\sqrt3$。',g=garden('3*x+1/x',0,1/math.sqrt(3),2*math.sqrt(3)),codes=['I07','I03','I04'])
add(8,1,2,terms=[r'$2(x-1)$',r'$1/(x-1)$'],discover=r'分母是一整块 $x-1$，前面却是 $2x$。',domain=r'令 $t=x-1$，由 $x>1$ 得 $t>0$。',routes=[('整体代换','整块起短名',r'塔莉：令 $t=x-1>0$，原式 $=2t+1/t+2$，两项积为 $2$。'),('构造','补齐前面的两份',r'法比娅：$2x=2(x-1)+2$，原式 $=2(x-1)+1/(x-1)+2\ge2\sqrt2+2$。')],eq=r'$2t=1/t$，所以 $t^2=1/2$，$x=1+\sqrt2/2$。',wrong=r'$x=\sqrt2/2$',pit=r'这是 $t$ 的值，原字母还要加 $1$；它也不满足 $x>1$。',calc=r'$2x+1/(x-1)\ge A+B\sqrt2$',fill=[('常数 $A=$',2),('系数 $B=$',2)],answer={'最小值':r'2+2\sqrt2','取到':r'x=1+\sqrt2/2'},check=r'$t=\sqrt2/2$ 时 $2t=1/t=\sqrt2$，再加 $2$。',g=garden('2*x+1/(x-1)',1,1+math.sqrt(.5),2+2*math.sqrt(2)),codes=['I-chain-17','I08','I07'])
add(8,2,0,terms=[r'$t$',r'$1/t$'],discover=r'$x^2-4x+8=(x-2)^2+4$ 是重复的一块。',domain=r'$t=(x-2)^2+4\ge4$，不能只写 $t>0$。',routes=[('整体代换','名字和范围一起打包',r'塔莉：令 $t=(x-2)^2+4\ge4$，原式 $=t-1+1/t$；与 $13/4$ 作差得 $(t-4)(4t-1)/(4t)\ge0$。'),('函数思想','看新范围里的变化',r'芙洛：$v>u\ge4$ 时，$[v-1+1/v]-[u-1+1/u]=(v-u)(1-1/(uv))>0$，最小在 $t=4$。')],eq=r'$t=4$，即 $(x-2)^2=0$，所以 $x=2$。',wrong=r'$t=1$，最小值为 $1$',pit=r'$t=(x-2)^2+4\ge4$，不能等于 $1$。',calc=r'$t=4\Rightarrow t-1+1/t=\square$',fill=[('最小值',3.25),('原字母 $x=$',2)],answer={'最小值':3.25,'取到':'x=2'},check=r'$x=2$ 时原式 $=3+1/4=13/4$。',extra=[r'$t=(x-2)^2+4\ge4$，原式 $=t-1+1/t$。',r'$t-1+1/t-13/4=\dfrac{(t-4)(4t-1)}{4t}\ge0$。',r'当且仅当 $t=4$，即 $x=2$ 时，等号成立，所以最小值为 $13/4$。'],g=garden('x-1+1/x',4,4,3.25,op='≥',change=[{'op':'≥','a':4},{'op':'≥','a':5},{'op':'>','a':5}]),garden_note='菜园接口只有 x，本关菜园的 x 表示换元后的 t，不是题面原字母。',codes=['I-chain-06','I08','I03'],equal_visual=False)
add(8,3,1,terms=[r'$x$',r'$2/x$'],discover=r'由 $x+2y=2$，得 $1-y=x/2$。',domain=r'$x>0,y>0$ 给出 $0<x<2$。',routes=[('整体代换','把分母整块换掉',r'塔莉：将 $1-y$ 整块换为 $x/2$，原式 $=x+2/x\ge2\sqrt2$。'),('构造','和下界凑平方',r'法比娅：原式 $=x+2/x$，与 $2\sqrt2$ 的差是 $(x-\sqrt2)^2/x\ge0$。')],eq=r'$x=\sqrt2\in(0,2)$，$y=(2-\sqrt2)/2>0$。',wrong=r'$x=2,y=0$',pit=r'$y=0$ 不满足正数条件，且两项 $2$ 与 $1$ 不相等。',calc=r'$x+2/x\ge A\sqrt2,\quad x^2=B$',fill=[('系数 $A=$',2),('$B=$',2)],answer={'最小值':r'2\sqrt2','取到':r'x=\sqrt2,y=(2-\sqrt2)/2'},check=r'$1-y=\sqrt2/2$，原式 $=\sqrt2+\sqrt2=2\sqrt2$。',g=garden('x+2/x',0,math.sqrt(2),2*math.sqrt(2),b=2),codes=['I08','I05','I03'])
add(9,1,-1,terms=[r'$2y/x$',r'$x/(2y)$'],discover=r'条件给出 $(x+2y)/2=1$，整圈绳子值为 $1$。',domain=r'$x>0,2y>0$，交叉两项相乘为 $1$。',routes=[('构造','乘上值为一的式子',r'法比娅：乘 $(x+2y)/2$，原式 $=\frac12(2+2y/x+x/(2y))\ge2$。'),('整体代换','比例整块起名',r'塔莉：令 $u=x/(2y)>0$，原式 $=\frac12(2+u+1/u)\ge2$。')],eq=r'$x=2y$，与 $x+2y=2$ 得 $x=1,y=1/2$。',wrong=r'乘 $x+2y$ 后原式的值不变',pit=r'$x+2y=2$，直接乘会放大一倍；要保留前面的 $1/2$。',calc=r'$\frac12(2+2)=\square$',fill=[('最小值',2),('取到时 $x=$',1)],answer={'最小值':2,'取到':'x=1,y=1/2'},check=r'$1/x+1/(2y)=1+1=2$。',g=garden('1/x+1/(2-x)',0,1,2,b=2),codes=['I-chain-16','I07','I03'])
add(9,2,0,terms=[r'$2y/x$',r'$2x/y$'],discover=r'$2/y=4/(2y)$，分母和条件里的两块能对齐。',domain=r'$x>0,2y>0$，两分母和为 $2$。',routes=[('构造','乘一后保留交叉项',r'法比娅：原式 $=\frac12(5+2y/x+2x/y)\ge\frac12(5+4)=9/2$。'),('整体代换','用比例收起两个字母',r'塔莉：令 $u=x/y>0$，原式 $=\frac12(5+2/u+2u)\ge9/2$。')],eq=r'$2y/x=2x/y$，正数下得 $x=y=2/3$。',wrong=r'$x=2y$',pit=r'这里的交叉两项是 $2y/x,2x/y$；相等要求 $x=y$。',calc=r'$\frac12(5+4)=\square$',fill=[('最小值',4.5),('取到时 $x=$',2/3)],answer={'最小值':4.5,'取到':'x=y=2/3'},check=r'$x+2y=2$，$1/x+2/y=3/2+3=9/2$。',g=garden('1/x+4/(2-x)',0,2/3,4.5,b=2),codes=['I-chain-16','I07','I03'])
add(9,3,1,terms=[r'$4y/x$',r'$3x/(2y)$'],discover=r'分子 $2,3$ 分别是 $(\sqrt2)^2,(\sqrt3)^2$。',domain=r'$x>0,2y>0$；交叉两项积为 $6$。',routes=[('构造','乘一留住四项',r'法比娅：原式 $=\frac12(5+4y/x+3x/(2y))\ge(5+2\sqrt6)/2$。'),('整体代换','给比值起名',r'塔莉：令 $u=x/(2y)>0$，原式 $=\frac12(5+2/u+3u)\ge(5+2\sqrt6)/2$。')],eq=r'$x/(2y)=\sqrt{2/3}$，联立条件得 $x=2\sqrt6-4,y=3-\sqrt6$。',wrong=r'$x=2y$',pit=r'两个权重不同；相等应是 $2/u=3u$，即 $u^2=2/3$。',calc=r'$\min F=(A+B\sqrt6)/2$',fill=[('常数 $A=$',5),('系数 $B=$',2)],answer={'最小值':r'(5+2\sqrt6)/2','取到':r'x=2\sqrt6-4,y=3-\sqrt6'},check=r'$x+2y=2$，且 $4y/x=3x/(2y)=\sqrt6$。',g=garden('2/x+3/(2-x)',0,2*math.sqrt(6)-4,(5+2*math.sqrt(6))/2,b=2),codes=['I07','I03','I04'])
add(10,1,-1,terms=[r'$x/2$',r'$y$'],discover=r'一次式的系数是 $2,1$，平方和是 $4$。',domain=r'$x,y$ 不限正负；求最大值要选正的比例。',routes=[('构造','补出非负平方',r'法比娅：$5(x^2+y^2)-(2x+y)^2=(x-2y)^2\ge0$，故 $(2x+y)^2\le20$。'),('方程思想','把取等比例列成方程',r'芭兰：由柯西 $(2x+y)^2\le(2^2+1^2)(x^2+y^2)=20$；令 $x=2c,y=c$，再解 $5c^2=4$。')],eq=r'$x=4\sqrt5/5,y=2\sqrt5/5$，取正比例。',wrong=r'$x=-4\sqrt5/5,y=-2\sqrt5/5$',pit=r'这组满足平方和，但 $2x+y=-2\sqrt5$，给的是最小值。',calc=r'$\max(2x+y)=A\sqrt5,\quad y^2=B$',fill=[('系数 $A=$',2),('$B=$',.8)],answer={'最大值':r'2\sqrt5','取到':r'x=4\sqrt5/5,y=2\sqrt5/5'},check=r'$x^2+y^2=16/5+4/5=4$，$2x+y=2\sqrt5$。',g={'跳过':'平方和约束对应圆，消元有正负两支；本接口不能同时表达两支。'},codes=['I01','I03','I04'])
add(10,2,0,terms=[r'$x/3$',r'$y/4$'],discover=r'系数平方和 $3^2+4^2=25$，不是 $7$。',domain=r'$x,y$ 为实数；$x^2+y^2\ge0$。',routes=[('构造','补出另一组平方',r'法比娅：$25(x^2+y^2)-(3x+4y)^2=(4x-3y)^2\ge0$；已知一次式为 $5$，得平方和至少 $1$。'),('方程思想','用同一倍数解条件',r'芭兰：由柯西 $25(x^2+y^2)\ge25$。取等设 $x=3c,y=4c$，代回得 $25c=5$。')],eq=r'$c=1/5$，所以 $x=3/5,y=4/5$。',wrong=r'$x=y=5/7$',pit=r'虽满足一次条件，却不满足 $x/3=y/4$；平方和为 $50/49>1$。',calc=r'$25(x^2+y^2)\ge25$',fill=[('最小值',1),('取到时 $x=$',.6)],answer={'最小值':1,'取到':'x=3/5,y=4/5'},check=r'$3(3/5)+4(4/5)=5$，$9/25+16/25=1$。',g={'跳过':'可消元为全实数二次式，但接口定义域只支持有下界区间，不能原样表达全实数域。'},codes=['I07','I03','I04'])
add(10,3,1,terms=[r'$x$',r'$y/2$'],discover=r'一次式的系数是 $1,2$，平方和是 $9$。',domain=r'$x,y$ 不限正负；上界需要正比例取到。',routes=[('构造','用平方补上差',r'法比娅：$5(x^2+y^2)-(x+2y)^2=(2x-y)^2\ge0$，所以 $(x+2y)^2\le45$。'),('方程思想','联立比例与平方和',r'芭兰：柯西给 $(x+2y)^2\le45$。取等设 $x=c,y=2c$，解 $5c^2=9$，选正根。')],eq=r'$x=3\sqrt5/5,y=6\sqrt5/5$。',wrong=r'$x=6\sqrt5/5,y=3\sqrt5/5$',pit=r'比例反了；应是 $y=2x$，这组目标值只有 $12\sqrt5/5<3\sqrt5$。',calc=r'$\max(x+2y)=A\sqrt5,\quad x^2=B$',fill=[('系数 $A=$',3),('$B=$',1.8)],answer={'最大值':r'3\sqrt5','取到':r'x=3\sqrt5/5,y=6\sqrt5/5'},check=r'$x^2+y^2=9/5+36/5=9$，$x+2y=3\sqrt5$。',g={'跳过':'平方和约束对应圆，消元有正负两支；本接口不能同时表达两支。'},codes=['I01','I03','I04'])
add(11,1,-1,terms=[r'$2y/x$',r'$2x/y$'],discover=r'链子卡住了 $x=y=1$：它们的加权和是 $3$。',domain=r'$x>0,y>0$ 且 $x+2y=2$，因此 $x<2,y<1$。',routes=[('存在性检验','先查两个等号能否一起发生',r'瑟塔：分组给 $G\ge6$，取等却要 $x=y=1$，不合法。改为 $G=2+1/x+2/y\ge2+9/2=13/2$。'),('构造','先收起固定的和',r'法比娅：$G=2+\frac12(5+2y/x+2x/y)\ge2+9/2=13/2$，两次相等都要求 $x=y$。')],eq=r'$x=y=2/3$，同时满足取等和原条件。',wrong=r'$x=y=1$，所以最小值为 $6$',pit=r'$1+2\times1=3\ne2$；得到下界，不代表最小值就是它。',calc=r'$G\ge2+9/2=\square$',fill=[('最小值',6.5),('取到时 $x=$',2/3)],answer={'最小值':6.5,'取到':'x=y=2/3'},check=r'$x+2y=2$，$G=2+3/2+3=13/2$。',g=garden('2+1/x+4/(2-x)',0,2/3,6.5,b=2),codes=['I-chain-05','I03','I04'],layers=5)
add(11,2,0,terms=[r'$1/x$',r'$1/y$'],discover=r'先把 $x+y$ 整块收起，再估两个倒数。',domain=r'第一问 $0<x<1$；第二问 $0<x<2$。',routes=[('存在性检验','两问分别查取等',r'瑟塔：第一问 $x=y=1$ 不合法；$1/x+1/y\ge4/(x+y)$。第一问最小 $1+4=5$；第二问最小 $2+2=4$。'),('整体代换','给固定的和起名',r'塔莉：令 $s=x+y$，原式 $=s+s/(xy)$；$xy\le s^2/4$，故原式至少 $s+4/s$。分别代 $s=1,2$。')],eq=r'第一问 $x=y=1/2$；第二问 $x=y=1$。',wrong=r'两问都取 $x=y=1$',pit=r'第一问要求和为 $1$，这组的和却为 $2$；改条件后不能沿用相等点。',calc=r'$s+4/s$：分别代入 $s=1$ 和 $s=2$',fill=[('第一问最小值',5),('第二问最小值',4)],answer={'第一问最小值':5,'第二问最小值':4,'取到':'第一问x=y=1/2；第二问x=y=1'},check=r'第一问 $1+2+2=5$；第二问 $2+1+1=4$，各自的和都对。',g=garden('1+1/x+1/(1-x)',0,.5,5,b=1),garden_note='菜园承接第一问 x+y=1；第二问在战斗和落笔中完整作答。',codes=['I-chain-05','I03','I04'],layers=5)
add(11,3,1,terms=[r'$8y/x$',r'$x/(2y)$'],discover=r'$x=2$ 与 $2y=1$ 不能同时满足和为 $2$。',domain=r'$0<x<2,0<y<1$，两个分母都正。',routes=[('存在性检验','先否掉取不到的六',r'瑟塔：分组取等要求 $x=2,y=1/2$，原条件不合；改为 $2+4/x+1/(2y)\ge2+(2+1)^2/2=13/2$。'),('构造','把剩下两项乘一',r'法比娅：$4/x+1/(2y)=\frac12(5+8y/x+x/(2y))\ge9/2$；再加固定和 $2$。')],eq=r'$8y/x=x/(2y)$，得 $x=4y$，所以 $x=4/3,y=1/3$。',wrong=r'$x=2,y=1/2$',pit=r'两项各自取等，却有 $x+2y=3$，不满足原条件。',calc=r'$G\ge2+\frac12(5+4)=\square$',fill=[('最小值',6.5),('取到时 $x=$',4/3)],answer={'最小值':6.5,'取到':'x=4/3,y=1/3'},check=r'$x+2y=2$，$4/x+1/(2y)=3+3/2=9/2$。',extra=[r'$x+2y=2$，原式 $=2+4/x+1/(2y)$。',r'$4/x+1/(2y)=\frac12(5+8y/x+x/(2y))\ge\frac12(5+4)=9/2$。',r'当且仅当 $8y/x=x/(2y)$，即 $x=4y$ 时，等号成立。',r'联立原条件得 $x=4/3,y=1/3$，均为正，最小值为 $13/2$。'],g=garden('2+4/x+1/(2-x)',0,4/3,6.5,b=2),codes=['I-chain-05','I03','I07'])
add(12,1,-1,terms=[r'$x$',r'$2y$'],discover=r'$x+2y=3-xy$；右边仍会变，不能当定值。',domain=r'$x,y>0$，所以 $xy>0$ 且 $3-xy>0$。',routes=[('整体代换','把积的平方根打包',r'塔莉：令 $u=\sqrt{xy}>0$。$3-u^2\ge2\sqrt2 u$，所以 $(u+\sqrt2)^2\le5$，得 $xy\le7-2\sqrt{10}$。'),('方程思想','消去一个字母再作差',r'芭兰：$y=(3-x)/(x+2),0<x<3$。令 $r=\sqrt{10}-2$，有 $7-2\sqrt{10}-xy=(x-r)^2/(x+2)\ge0$。')],eq=r'$x=2y$，得 $x=\sqrt{10}-2,y=(\sqrt{10}-2)/2$。',wrong=r'$xy=\sqrt5-\sqrt2$',pit=r'$u$ 才是平方根，回到积要算 $xy=u^2$，不能直接换名字。',calc=r'$\max xy=A-B\sqrt{10}$',fill=[('常数 $A=$',7),('系数 $B=$',2)],answer={'最大值':r'7-2\sqrt{10}','取到':r'x=\sqrt{10}-2,y=(\sqrt{10}-2)/2'},check=r'$x+2y=2\sqrt{10}-4$，$xy=7-2\sqrt{10}$，相加恰为 $3$。',g=garden('x*(3-x)/(x+2)',0,math.sqrt(10)-2,7-2*math.sqrt(10),'最大值',b=3),codes=['I-chain-18','I08','I04'],layers=5)
add(12,2,0,terms=[r'$a$',r'$b$'],discover=r'$a+b=ab-3$，和与积绑在一起。',domain=r'$a,b>0$，且 $(a-1)(b-1)=4$，可得 $a,b>1$。',routes=[('整体代换','把积的平方根起名',r'塔莉：令 $t=\sqrt{ab}>0$，$t^2\ge2t+3$，得 $(t-3)(t+1)\ge0$，故 $ab\ge9$。'),('方程思想','先解出一个字母',r'芭兰：$b=(a+3)/(a-1)$，$a>1$；$ab-9=(a-3)^2/(a-1)\ge0$。且此连续式在 $a\ge3$ 从 $9$ 增至无穷。')],eq=r'$a=b=3$ 取到 $9$；所有 $p\ge9$ 都能取到。',wrong=r'只验 $a=b=3$ 就证明了整个范围',pit=r'这只证明端点能取到；还要说明每个 $p>9$ 也有正数解。',calc=r'$ab\in[A,+\infty),\quad a=b=B$ 时取到左端',fill=[('左端 $A=$',9),('取等 $B=$',3)],answer={'范围':'[9,+∞)','左端':9,'取到':'a=b=3'},check=r'任取 $p\ge9$，$D=(p-1)(p-9)\ge0$，$a,b=(p-3\pm\sqrt D)/2$ 均正、和为 $p-3$、积为 $p$。',g=garden('x*(x+3)/(x-1)',1,3,9),garden_note='菜园的 x 表示题面 a；范围证明和左端最值均完整保留。',codes=['I08','I04','I03'],layers=5)
add(12,3,1,terms=[r'$x$',r'$2y$'],discover=r'$x+2y=4-2xy$；积越大，目标中的和越小。',domain=r'$x,y>0$，由条件得 $0<x<4$。',routes=[('整体代换','先给积起名再还原和',r'塔莉：令 $u=\sqrt{xy}>0$，$4-2u^2\ge2\sqrt2u$，得 $xy\le3-\sqrt5$；因此和至少 $2\sqrt5-2$。'),('方程思想','消去字母并配平方',r'芭兰：$y=(4-x)/(2+2x)$，和 $=(x^2+4)/(x+1)$。令 $r=\sqrt5-1$，与 $2\sqrt5-2$ 的差为 $(x-r)^2/(x+1)\ge0$。')],eq=r'$x=2y$，解得 $x=\sqrt5-1,y=(\sqrt5-1)/2$。',wrong=r'最小值就是 $3-\sqrt5$',pit=r'这是积的上界，题目要和；应代回 $x+2y=4-2xy$。',calc=r'$\min(x+2y)=A\sqrt5-B$',fill=[('系数 $A=$',2),('常数 $B=$',2)],answer={'最小值':r'2\sqrt5-2','取到':r'x=\sqrt5-1,y=(\sqrt5-1)/2'},check=r'$x+2y=2\sqrt5-2$，$2xy=6-2\sqrt5$，两者相加为 $4$。',g=garden('(x*x+4)/(x+1)',0,math.sqrt(5)-1,2*math.sqrt(5)-2,b=4),codes=['I-chain-18','I01','I08'],layers=5)
add(13,1,-1,terms=[r'$x$',r'$2y$'],discover=r'设靠墙边长为 $x$，垂直墙的边长为 $y$，只围三边。',domain=r'$x,y>0,xy=64$；墙足够长。',routes=[('放缩','用固定面积估三边和',r'玛尔嘉：$L=x+2y\ge2\sqrt{2xy}=16\sqrt2$。'),('方程思想','用面积消去另一边',r'芭兰：$y=64/x$，$L=x+128/x$；$L-16\sqrt2=(x-8\sqrt2)^2/x\ge0$。')],eq=r'$x=2y$，得 $x=8\sqrt2,y=4\sqrt2$，墙足够长。',wrong=r'$x=y=8$，正方形一定最省',pit=r'只围三边，正方形需 $24$ 米，大于 $16\sqrt2$ 米。',calc=r'$x=A\sqrt2,\ y=B\sqrt2,\ L=C\sqrt2$',fill=[('靠墙边系数 $A=$',8),('另一边系数 $B=$',4),('最短篱笆系数 $C=$',16)],answer={'最短':r'16\sqrt2 米','长宽':r'靠墙8\sqrt2米，垂直4\sqrt2米'},check=r'面积 $(8\sqrt2)(4\sqrt2)=64$，三边总长为 $16\sqrt2$。',g=garden('x+128/x',0,8*math.sqrt(2),16*math.sqrt(2)),codes=['I07','I03','I04'],layers=3)
add(13,2,0,terms=[r'$x$',r'$128/x$'],discover=r'靠墙边 $x$ 只能到 $10$ 米，三边和仍为 $x+128/x$。',domain=r'$0<x\le10$；公式取等点 $8\sqrt2>10$ 不可用。',routes=[('放缩','用实际范围给差定方向',r'玛尔嘉：$L-114/5=(x-10)(5x-64)/(5x)\ge0$，两个因子都非正，分母正。'),('方程思想','消去靠墙边',r'芭兰：$y=64/x\ge32/5$。$L=2y+64/y$；与 $114/5$ 的差为 $(y-32/5)(2-10/y)\ge0$。')],eq=r'$x=10,y=32/5$，最短为 $114/5$ 米。',wrong=r'仍取 $x=8\sqrt2,y=4\sqrt2$',pit=r'靠墙边超过 $10$ 米，实际放不下；不能沿用原来的相等点。',calc=r'$L(10)=10+128/10=\square$',fill=[('最短篱笆（米）',22.8),('靠墙边（米）',10),('垂直墙的边（米）',6.4)],answer={'最短':22.8,'靠墙边':10,'垂直边':6.4},check=r'$10\times6.4=64$，$10+2\times6.4=22.8$，靠墙边正好放下。',g=garden('2*x+64/x',6.4,6.4,22.8,op='≥',change=[{'op':'≥','a':6.4},{'op':'≥','a':7},{'op':'>','a':7}]),garden_note='菜园的 x 表示垂直墙的 y，以保留墙长上界对应的 y≥32/5；三改均不放宽原约束。',codes=['I-chain-06','I03','I04'],equal_visual=False,layers=3)
