add(13,3,1,terms=[r'$3600/x$',r'$4x$'],discover=r'一年运费为 $6\times600/x=3600/x$，还要加存储费 $4x$。',domain=r'$0<x\le600$，一年购买次数 $600/x$ 应为正整数。',routes=[('特殊化','先试一组再证明下界',r'苔丝：先试每次 $30$ 吨，年购 $20$ 次，费用 $240$。这还不是证明；$F-240=4(x-30)^2/x\ge0$，所以任何合法值都不会更少。'),('放缩','先估连续范围再查次数',r'玛尔嘉：$3600/x+4x\ge2\sqrt{14400}=240$，取等 $x=30$；购买次数为 $20$，确实合法。')],eq=r'$x=30$ 吨，一年买 $20$ 次，费用 $240$ 万元。',wrong=r'$x=600$，买一次一定最省',pit=r'虽省运费，存储费变大；这时 $F=6+2400=2406$ 万元。',calc=r'$3600/x=4x\Rightarrow x^2=900$',fill=[('每次购买量（吨）',30),('最低年费用（万元）',240),('一年购买次数',20)],answer={'购买量':30,'最小费用':240,'次数':20},check=r'$600/30=20$ 是整数，$3600/30+4\times30=240$。',g={'跳过':'购买次数必须为正整数；连续区间三改会误报开端点取不到，接口不能表达这一离散约束。'},codes=['I07','I03','I04'],layers=3)
